package com.finanscore.scoring.infrastructure;import jakarta.persistence.*;import java.time.*;import java.util.*;@Entity @Table(name="evaluation_input_snapshot") public class EvaluationInputSnapshotEntity{@Id public UUID id;@Column(name="request_id",nullable=false,unique=true)public UUID requestId;@Column(name="user_id",nullable=false)public Long userId;@Lob @Column(name="input_json",nullable=false,columnDefinition="TEXT")public String inputJson;@Column(name="created_at",nullable=false)public Instant createdAt;}